(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:'',ticketId:null};
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('../../../api/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Support request failed.');return data;}
  function status(text,error=false){el('vsp-status').textContent=text;el('vsp-status').className='vc-status '+(error?'warning':'info');}
  function cell(row,text){const td=document.createElement('td');td.textContent=String(text??'—');row.append(td);return td;}
  async function list(){try{const [identity,data]=await Promise.all([call('vendor/auth/me.php'),call('support.php?limit=100')]);state.csrf=identity.csrf_token||'';const body=el('vsp-rows');body.replaceChildren();if(!data.tickets.length){cell(body.appendChild(document.createElement('tr')),'No support tickets yet.').colSpan=6;}data.tickets.forEach(ticket=>{const row=document.createElement('tr');cell(row,ticket.ticket_number);cell(row,ticket.subject);cell(row,ticket.category);cell(row,ticket.status.replaceAll('_',' '));cell(row,ticket.updated_at);const action=document.createElement('td');const button=document.createElement('button');button.type='button';button.className='vc-btn small';button.textContent='View';button.addEventListener('click',()=>detail(ticket.id));action.append(button);row.append(action);body.append(row);});status(data.pagination.total+' support tickets');}catch(error){status(error.message,true);}}
  async function detail(id){try{const data=await call('support.php?id='+encodeURIComponent(id));const ticket=data.ticket;state.ticketId=id;el('vsp-detail-title').textContent=ticket.ticket_number+' · '+ticket.subject;const wrap=el('vsp-messages');wrap.replaceChildren();(ticket.messages||[]).forEach(message=>{const row=document.createElement('div');row.className='vc-list-item';const copy=document.createElement('div');copy.className='vc-list-copy';const heading=document.createElement('strong');heading.textContent=message.senderName+' · '+message.createdAt;const p=document.createElement('p');p.textContent=message.message;copy.append(heading,p);row.append(copy);wrap.append(row);});el('vsp-reply').hidden=['closed','resolved'].includes(ticket.status);el('vsp-detail').hidden=false;el('vsp-detail').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){status(error.message,true);}}
  el('vsp-new').addEventListener('click',()=>{el('vsp-form').reset();el('vsp-dialog').showModal();});el('vsp-close').addEventListener('click',()=>el('vsp-dialog').close());el('vsp-hide').addEventListener('click',()=>{el('vsp-detail').hidden=true;state.ticketId=null;});
  el('vsp-form').addEventListener('submit',async event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;const button=event.submitter;button.disabled=true;try{const result=await call('support.php','POST',Object.fromEntries(new FormData(event.currentTarget)));el('vsp-dialog').close();await list();await detail(result.ticket_id);}catch(error){status(error.message,true);}finally{button.disabled=false;}});
  el('vsp-reply').addEventListener('submit',async event=>{event.preventDefault();if(!state.ticketId||!event.currentTarget.reportValidity())return;const button=event.submitter;button.disabled=true;try{await call('support.php','POST',{ticket_id:state.ticketId,message:event.currentTarget.elements.namedItem('message').value});event.currentTarget.reset();await detail(state.ticketId);await list();}catch(error){status(error.message,true);}finally{button.disabled=false;}});
  list();
})();
